#!/usr/bin/env bash
set -euo pipefail

# Roll out the AlphaEvolve winning configuration using native Vertex AI (`gcloud ai`) CLI:
MODEL_ID=$(gcloud ai models upload \
  --project=${GCP_PROJECT_ID} \
  --region=${GCP_REGION:-us-central1} \
  --display-name=alpha-inference-best \
  --container-image-uri=docker.io/vllm/vllm-openai:v0.31.0 \
  --container-command='^||^bash||-lc||mkdir -p /tmp/ae_kernel && python3 -c "import base64; import os; import pathlib; pathlib.Path('"'"'/tmp/ae_kernel/sitecustomize.py'"'"').write_bytes(base64.b64decode(os.environ['"'"'AE_KERNEL_B64'"'"']))" && export PYTHONPATH="/tmp/ae_kernel:${PYTHONPATH:-}" && exec vllm serve "$@"||--' \
  --container-args='^||^google/gemma-4-26B-A4B-it||--served-model-name=google/gemma-4-26B-A4B-it||--host=0.0.0.0||--port=8080||--max-model-len=8192||--max-logprobs=16||--gpu-memory-utilization=0.95||--quantization=fp8||--kv-cache-dtype=fp8||--language-model-only||--async-scheduling||--max-num-seqs=256||--max-num-batched-tokens=4096||--long-prefill-token-threshold=1024||--speculative-config={"method":"ngram_gpu","num_speculative_tokens":2,"prompt_lookup_max":4,"prompt_lookup_min":2}||--compilation-config={"cudagraph_capture_sizes":[1,2,4,8,16,24,32,40,48,56,64,72,80,88,96,104,112,120,128,136,144,152,160,168,176,184,192,200,208,216,224,232,240,248,256,272,288,304,320,336,352,368,384,400,416,432,448,464,480,496,512],"max_cudagraph_capture_size":512}||--disable-uvicorn-access-log' \
  --container-env-vars='^||^PYTHONUNBUFFERED=1||TOKENIZERS_PARALLELISM=false||HF_HOME=/dev/shm/hf_cache||AE_KERNEL_' \
  --container-ports=8080 \
  --container-predict-route=/v1/chat/completions \
  --container-health-route=/health \
  --container-shared-memory-size-mb=83968 \
  --container-deployment-timeout-seconds=3600 \
  --format='value(model)' --quiet)

gcloud ai endpoints deploy-model ${VERTEX_ENDPOINT_ID} \
  --project=${GCP_PROJECT_ID} \
  --region=${GCP_REGION:-us-central1} \
  --model="$MODEL_ID" \
  --display-name=alpha-inference-best \
  --machine-type=g4-standard-48 \
  --accelerator=type=nvidia-rtx-pro-6000,count=1 \
  --min-replica-count=1 --max-replica-count=1 \
  --traffic-split=0=100 --quiet
